package java.util.concurrent;
import java.util.*;
public class LinkedBlockingQueue<E> extends AbstractQueue<E> implements BlockingQueue<E>,java.io.Serializable {
 private final LinkedBlockingDeque<E> q; public LinkedBlockingQueue(){q=new LinkedBlockingDeque<E>();} public LinkedBlockingQueue(int capacity){q=new LinkedBlockingDeque<E>(capacity);} public LinkedBlockingQueue(Collection<? extends E> c){this();addAll(c);} public int size(){return q.size();} public int remainingCapacity(){return q.remainingCapacity();} public Iterator<E> iterator(){return q.iterator();} public boolean offer(E e){return q.offer(e);} public E poll(){return q.poll();} public E peek(){return q.peek();} public void put(E e)throws InterruptedException{q.put(e);} public boolean offer(E e,long n,TimeUnit u)throws InterruptedException{return q.offer(e,n,u);} public E take()throws InterruptedException{return q.take();} public E poll(long n,TimeUnit u)throws InterruptedException{return q.poll(n,u);} public int drainTo(Collection<? super E> c){return drainTo(c,Integer.MAX_VALUE);} public int drainTo(Collection<? super E> c,int n){if(c==this)throw new IllegalArgumentException();return q.drainTo(c,n);} public boolean remove(Object o){return q.remove(o);} public void clear(){q.clear();}
}